      "output_example": "results: {'/path/to/image_single': [(8.7, 0.5, -2.1, 0.89)],\n '/path/to/image_multi':  [(12.3, -5.6, 0.2, 0.91), (-31.0, 3.4, -6.2, 0.88)]}\n"
    },
